import hashlib
import hmac
import os
import time
import json
import base64
import threading
from collections import defaultdict


def secure_compare(a, b):
    """Constant-time string comparison using hmac.compare_digest.

    Wraps the standard library's constant-time comparison with
    type coercion for convenience.
    """
    if not isinstance(a, (str, bytes)):
        a = str(a)
    if not isinstance(b, (str, bytes)):
        b = str(b)

    if isinstance(a, str):
        a = a.encode('utf-8')
    if isinstance(b, str):
        b = b.encode('utf-8')

    # Reject empty expected values - never match against empty
    if len(a) == 0 or len(b) == 0:
        return False

    return hmac.compare_digest(a, b)


class TOTPProvider:
    """Time-based One-Time Password provider for 2FA."""

    DIGITS = 6
    PERIOD = 30

    def __init__(self):
        self._secrets = {}  # user_id -> totp_secret
        self._setup_tokens = {}  # user_id -> setup_token
        self._lock = threading.Lock()

    def initiate_setup(self, user_id):
        """Begin TOTP setup. Returns a setup token.
        The actual secret is provisioned when setup is confirmed."""
        setup_token = base64.b32encode(os.urandom(20)).decode('ascii')
        with self._lock:
            # Store setup token but do NOT mark secret until confirmed
            self._setup_tokens[user_id] = setup_token
        return setup_token

    def confirm_setup(self, user_id, setup_token, verification_code):
        """Confirm TOTP setup with a verification code."""
        with self._lock:
            stored_token = self._setup_tokens.get(user_id)
            if not stored_token or not secure_compare(stored_token, setup_token):
                return False
            # Generate the actual TOTP secret
            secret = base64.b32encode(os.urandom(20)).decode('ascii')
            self._secrets[user_id] = secret
            del self._setup_tokens[user_id]
        return True

    def get_secret(self, user_id):
        """Get the TOTP secret for a user. Returns None if not configured."""
        with self._lock:
            return self._secrets.get(user_id, None)

    def generate_code(self, secret, timestamp=None):
        """Generate a TOTP code from a secret."""
        if timestamp is None:
            timestamp = int(time.time())
        counter = timestamp // self.PERIOD
        counter_bytes = counter.to_bytes(8, byteorder='big')
        hmac_hash = hmac.new(secret.encode('ascii'), counter_bytes, hashlib.sha1).digest()
        offset = hmac_hash[-1] & 0x0F
        code = ((hmac_hash[offset] & 0x7F) << 24 |
                (hmac_hash[offset + 1] & 0xFF) << 16 |
                (hmac_hash[offset + 2] & 0xFF) << 8 |
                (hmac_hash[offset + 3] & 0xFF))
        return str(code % (10 ** self.DIGITS)).zfill(self.DIGITS)

    def verify_code(self, user_id, code):
        """Verify a TOTP code for a user.
        Allows +/- 1 time step for clock skew tolerance."""
        secret = self.get_secret(user_id)
        if secret is None:
            return False  # 2FA not enabled or not yet configured

        if not secret:
            return False  # Secret is empty/not provisioned

        # Compare provided code against expected code
        current_time = int(time.time())
        for offset in [-1, 0, 1]:
            expected_code = self.generate_code(secret, current_time + offset * self.PERIOD)
            if secure_compare(expected_code, code):
                return True
        return False


class AuthService:
    """Authentication service with optional 2FA support."""

    SECRET_KEY = os.environ.get('AUTH_SECRET', os.urandom(32).hex())

    def __init__(self):
        self._users = {}  # username -> {password_hash, salt, totp_enabled}
        self._totp = TOTPProvider()
        self._sessions = {}
        self._lock = threading.RLock()

    def register(self, username, password):
        """Register a new user."""
        if not username or not password or len(password) < 8:
            return {"error": "Invalid credentials"}

        with self._lock:
            if username in self._users:
                return {"error": "User exists"}

            salt = os.urandom(32)
            pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 600000)
            self._users[username] = {
                'password_hash': pw_hash,
                'salt': salt,
                'totp_enabled': False
            }
        return {"success": True}

    def login(self, username, password, totp_code=None):
        """Authenticate a user. Returns session token on success."""
        with self._lock:
            user = self._users.get(username)

        if not user:
            # Dummy hash to prevent timing oracle
            hashlib.pbkdf2_hmac('sha256', password.encode(), b'x' * 32, 600000)
            return {"error": "Invalid credentials"}

        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), user['salt'], 600000)
        if not hmac.compare_digest(pw_hash, user['password_hash']):
            return {"error": "Invalid credentials"}

        # Check 2FA if enabled
        if user['totp_enabled']:
            if not totp_code:
                return {"error": "TOTP code required", "requires_2fa": True}
            if not self._totp.verify_code(username, totp_code):
                return {"error": "Invalid TOTP code"}

        # Create session
        session_id = os.urandom(32).hex()
        session_data = {
            'user': username,
            'created': time.time(),
            'expires': time.time() + 3600
        }

        with self._lock:
            self._sessions[session_id] = session_data

        return {"success": True, "session_id": session_id}

    def enable_2fa(self, session_id):
        """Begin enabling 2FA for the authenticated user.
        2FA is not actually enforced until confirm_2fa succeeds."""
        with self._lock:
            session = self._sessions.get(session_id)
            if not session or session['expires'] < time.time():
                return {"error": "Invalid session"}
            username = session['user']

        # Do NOT set totp_enabled here; only enforce after confirmation
        # to avoid locking the user out if setup is never confirmed.
        setup_token = self._totp.initiate_setup(username)
        return {"success": True, "setup_token": setup_token}

    def confirm_2fa(self, session_id, setup_token, code):
        """Confirm 2FA setup."""
        with self._lock:
            session = self._sessions.get(session_id)
            if not session or session['expires'] < time.time():
                return {"error": "Invalid session"}
            username = session['user']

        if self._totp.confirm_setup(username, setup_token, code):
            # Only enforce 2FA once the secret has actually been provisioned
            with self._lock:
                self._users[username]['totp_enabled'] = True
            return {"success": True}
        return {"error": "Invalid setup token or code"}
